SELECT country, CASE WHEN rating >= 4.1 THEN 'high' WHEN rating >= 1.5 THEN 'mid' ELSE 'low' END AS rating_bucket, SORT_ARRAY(COLLECT_SET(country)) AS country_list, MAX(rating) - MIN(rating) AS rating_range FROM suppliers WHERE NOT (LENGTH(supplier_name) > 12 AND LENGTH(supplier_name) < 13 AND city NOT IN ('Bangkok', 'New York')) GROUP BY country, rating_bucket ORDER BY rating_bucket DESC, rating_range DESC
